       /* Fold the first cell and the mid columns left of the surface
        * into one column-0 cover update. */
       int32_t cx_skip = (int32_t) col_min; /* ≤ cx1, so it fits */
       fy_prev = fy_b + (int32_t) ((int64_t) (cx_skip - cx) * delta_fy);
